warp:
shader_body
{
vec2 _uv = uv;

    vec2 d = texsize.zw * 4.0;
    vec3 dx = ( ((texture(sampler_blur1, _uv + vec2(1.0,0.0)*d).xyz * scale1) + bias1) - ((texture(sampler_blur1, _uv-vec2(1.0,0.0)*d).xyz * scale1) + bias1) );
    vec3 dy = ( ((texture(sampler_blur1, _uv + vec2(0.0,1.0)*d).xyz * scale1) + bias1) - ((texture(sampler_blur1, _uv-vec2(0.0,1.0)*d).xyz * scale1) + bias1) );

    vec2 dither_uv = uv_orig*texsize.xy*texsize_noise_lq.zw * 1.2 + rand_frame.xy;

    vec2 my_uv = vec2(mix(uv_orig,_uv,1.0));
    vec2 uv_x= my_uv + vec2(dx.x,dy.x)*texsize.zw  *8.0;
    vec2 uv_y= my_uv + vec2(dx.y,dy.y)*texsize.zw  *8.0;
    vec2 uv_z= my_uv + vec2(dx.z,dy.z)*texsize.zw  *8.0;
    ret.x = texture(sampler_main, uv_x).xyz.x - (texture(sampler_main, uv_x).xyz - ((texture(sampler_blur3, uv_x).xyz * scale3) + bias3)).x  * 0.02;
    ret.y = texture(sampler_main, uv_y).xyz.y - (texture(sampler_main, uv_y).xyz - ((texture(sampler_blur3, uv_y).xyz * scale3) + bias3)).y  * 0.02;
    ret.z = texture(sampler_main, uv_z).xyz.z - (texture(sampler_main, uv_z).xyz - ((texture(sampler_blur3, uv_z).xyz * scale3) + bias3)).z  * 0.02;

//    ret += - 0.004  +(texture(sampler_noise_lq, dither_uv).xyz-0.5) *0.0;
ret -= ret.yzx*0.2 - 0.06;


}

comp:
shader_body
{

vec2 uv1 = vec2(uv-.5);

vec3 ret1 = texture(sampler_main, uv).xyz +texture(sampler_main, 1.0-uv).xyz*0.0;


vec2 hor = vec2 (texsize.z,0.0);
vec2 ver = vec2 (0.0,texsize.w);
float dx = (texture(sampler_main, uv-hor).xyz - texture(sampler_main, uv+hor).xyz).x;
float dy = (texture(sampler_main, uv-ver).xyz - texture(sampler_main, uv+ver).xyz).x;
vec2 dz = vec2 (dx,dy);

uv1 = .3*cos(uv1*2.0+1.7) -2.0*dz;
vec3 dots = vec3(clamp(.03/length(uv1), 0.0, 1.0));


ret1 = (-ret1/4.0) + 6.0*dots*(-0.08+ret1);

ret = ret1;



}
